const wh = $('Evolution Webhook').first().json;
const body = wh.body || wh;
const data = body.data || {};
const key = data.key || {};
const message = data.message || {};
const remoteJid = key.remoteJid || '';
const numero = remoteJid.split('@')[0].split(':')[0];
const esGrupo = remoteJid.indexOf('@g.us') !== -1;
const ext = message.extendedTextMessage || {};
const img = message.imageMessage || {};
const texto = message.conversation || ext.text || img.caption || '';
const hayImagen = !!message.imageMessage || data.messageType === 'imageMessage';
const tipo = hayImagen ? 'image' : (texto ? 'text' : 'otro');
const evento = String(body.event || '').toLowerCase().replace(/_/g, '.');
const procesable = evento === 'messages.upsert' && !key.fromMe && !esGrupo && remoteJid !== '' && tipo !== 'otro';
return [{ json: { evento, instancia: body.instance || '', remoteJid, numero, esGrupo, fromMe: !!key.fromMe, messageId: key.id || '', pushName: data.pushName || '', email: data.email || '', texto, tipo, procesable } }];

const msg = $('Normalize Evolution Event').first().json;
const fila = $json || {};
const estado = fila.estado || 'NUEVO';

const norm = function (s) { return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); };
const texto = norm(msg.texto);
const compacto = texto.replace(/ /g, '');
const esImagen = msg.tipo === 'image';

const FRASES_ACTIVACION = ['quiero registrarme para la jmj corea 2027', 'quiero registrarme para la jmj de corea 2027', 'quiero registrarme para corea 2027', 'quiero registrarme para la jmj', 'quiero registrarme para la jmj de seul 2027', 'quiero registrarme para la jmj seul 2027', 'quiero registrarme para la jmj 2027', 'quiero registrarme para seul 2027', 'quiero registrarme para la jmj de corea', 'quiero registrarme para la jmj de seul', 'quiero registrarme para corea', 'quiero registrarme para la jornada mundial de la juventud'];
const RE_ACTIVACION = /^quiero (?:registrarme|inscribirme|apuntarme|anotarme)\s*(?:para|a|al|en)?\s*(?:la|el|las|los)?\s*(?:jmj|jornada mundial de la juventud|jornada mundial de juventud|corea|seul|seoul|peregrinacion)\b/;
const esActivacion = FRASES_ACTIVACION.indexOf(texto) !== -1 || RE_ACTIVACION.test(texto);

const OPCIONES_PASAPORTE = ['pasaporte', 'conpasaporte', 'registroconpasaporte', 'registro'];
const OPCIONES_SIN_PASAPORTE = ['sinpasaporte', 'nopasaporte', 'notengopasaporte', 'registrosinpasaporte'];

const ESTADOS_SIN_PASAPORTE = ['SP_ESPERANDO_NOMBRE', 'SP_ESPERANDO_NACIMIENTO', 'SP_ESPERANDO_CURP', 'SP_ESPERANDO_SEXO'];

const MSG_BIENVENIDA = 'Para realizar su registro de peregrino responda con una de estas opciones:\n\n*Pasaporte* - si ya cuenta con su pasaporte y quiere registrarse con el.\n*Sin pasaporte* - si aun no tiene pasaporte y quiere registrarse de todas formas.';
const MSG_INSTRUCCIONES = 'Favor de mandar foto de su pasaporte COMPLETA, que salgan todos los datos incluidos los datos de la parte inferior del pasaporte (MRZ)';
const MSG_REINTENTO = 'De acuerdo, no daremos esos datos por correctos.\n\n' + MSG_INSTRUCCIONES;

let route = 'ignore';

if (esActivacion) {
  route = 'welcome';
} else if (esImagen) {
  route = (estado === 'ESPERANDO_FOTO' || estado === 'ESPERANDO_CONFIRMACION') ? 'ocr' : 'ignore';
} else if (estado !== 'NUEVO' && OPCIONES_SIN_PASAPORTE.indexOf(compacto) !== -1) {
  route = 'sin_pasaporte';
} else if (estado !== 'NUEVO' && OPCIONES_PASAPORTE.indexOf(compacto) !== -1) {
  route = 'instructions';
} else if (ESTADOS_SIN_PASAPORTE.indexOf(estado) !== -1) {
  route = 'sin_pasaporte';
} else if (estado === 'ESPERANDO_CONFIRMACION') {
  route = (compacto === 'ok' || compacto === 'okay' || compacto === 'okey') ? 'confirm' : 'retry_photo';
} else if (estado === 'ESPERANDO_FOTO') {
  route = 'instructions';
} else if (estado === 'ESPERANDO_PALABRA') {
  route = 'welcome';
}

const mensajes = { 
  welcome: MSG_BIENVENIDA, 
  instructions: MSG_INSTRUCCIONES, 
  retry_photo: MSG_REINTENTO, 
  confirm: '', 
  ocr: '', 
  sin_pasaporte: '', 
  ignore: '' 
};

return [{ 
  json: Object.assign({}, msg, { 
    estadoActual: estado, 
    filaId: fila.id || null, 
    route, 
    mensaje: mensajes[route] 
  }) 
}];

const ctx = $('Classify Route').first().json;
const full = $json || {};
const status = full.statusCode || 200;
const resp = full.body || full;
const fmt = function (iso) { if (!iso) { return '-'; } const p = String(iso).split('-'); return p.length === 3 ? (p[2] + '/' + p[1] + '/' + p[0]) : String(iso); };
const errores = { UNSUPPORTED_FILE_TYPE: 'El archivo enviado no es una imagen válida.', FILE_TOO_LARGE: 'La imagen pesa demasiado.', COMPRESSION_FAILED: 'No pudimos procesar la imagen por su tamaño.', PDF_PAGE_LIMIT_EXCEEDED: 'El documento tiene demasiadas páginas.', CORRUPT_OR_ENCRYPTED_FILE: 'El archivo está dañado o protegido.', OCR_SPACE_AUTH_ERROR: 'El servicio de lectura no está disponible en este momento.', OCR_SPACE_ERROR: 'El servicio de lectura no pudo procesar la imagen.' };
const REPETIR = '\n\nPor favor envíe de nuevo una foto de su pasaporte COMPLETA, bien iluminada y sin reflejos, que salgan todos los datos incluidos los de la parte inferior (MRZ).';
const mrz = (resp.passport || {}).mrz || null;
let ok = false;
let mensaje = '';
let datos = { nombre: '', apellidos: '', numero_pasaporte: '', nacionalidad: '', sexo: '', fecha_nacimiento: '', fecha_vencimiento: '', pais_emisor: '', numero_personal: '' };
if (status >= 400 || resp.success === false) {
  const code = ((resp.error || {}).code) || ('HTTP_' + status);
  mensaje = 'No pudimos leer su pasaporte. ' + (errores[code] || 'Ocurrió un problema al procesar la imagen.') + REPETIR;
} else if (!mrz) {
  mensaje = 'No pudimos detectar la zona MRZ (las dos líneas del pie de la página de datos) de su pasaporte.' + REPETIR;
} else if (mrz.checksum_valid !== true) {
  mensaje = 'La zona MRZ de su pasaporte no se leyó con claridad.' + REPETIR;
} else {
  ok = true;
  datos = { nombre: mrz.given_names || '', apellidos: mrz.surname || '', numero_pasaporte: mrz.passport_number || '', nacionalidad: mrz.nationality || '', sexo: mrz.sex || '', fecha_nacimiento: mrz.date_of_birth || '', fecha_vencimiento: mrz.date_of_expiry || '', pais_emisor: mrz.issuing_country || '', numero_personal: mrz.personal_number || '' };
  const aviso = (resp.passport || {}).matches_visible_text === false ? '\n\n_Revise con cuidado: algunos datos podrían no coincidir con el documento._' : '';
  mensaje = 'Estos son los datos que leímos de su pasaporte:\n\n' +
    '*Apellidos:* ' + datos.apellidos + '\n' +
    '*Nombre(s):* ' + datos.nombre + '\n' +
    '*No. de pasaporte:* ' + datos.numero_pasaporte + '\n' +
    '*Nacionalidad:* ' + datos.nacionalidad + '\n' +
    '*Sexo:* ' + datos.sexo + '\n' +
    '*Fecha de nacimiento:* ' + fmt(datos.fecha_nacimiento) + '\n' +
    '*Vence:* ' + fmt(datos.fecha_vencimiento) + aviso + '\n\n' +
    'Si todos los datos son correctos responda con la palabra *OK* para completar su registro.\n' +
    'Si algo no es correcto, envíe de nuevo una foto de su pasaporte.';
}
return [{ json: Object.assign({ ok: ok, mensaje: mensaje, numero: ctx.numero, remoteJid: ctx.remoteJid }, datos) }];

const ctx = $('Classify Route').first().json;
const fila = $('Get Session').first().json || {};
const LIMITE = '2028-03-01';
const venc = String(fila.fecha_vencimiento || '').slice(0, 10);
const vigenciaOk = /^\d{4}-\d{2}-\d{2}$/.test(venc) && venc >= LIMITE;
const MSG_EXITO = 'Felicidades! Ha creado correctamente su registro.';
const MSG_VIGENCIA = '⚠️ No es posible realizar el registro, el pasaporte tiene que tener vigencia mayor al 1 de marzo de 2028';
return [{ json: {
  email: ctx.email || '',
  remote_jid: ctx.remoteJid,
  numero: ctx.numero,
  nombre: fila.nombre || '',
  apellidos: fila.apellidos || '',
  numero_pasaporte: fila.numero_pasaporte || '',
  nacionalidad: fila.nacionalidad || '',
  sexo: fila.sexo || '',
  fecha_nacimiento: fila.fecha_nacimiento || '',
  fecha_vencimiento: venc,
  pais_emisor: fila.pais_emisor || '',
  numero_personal: fila.numero_personal || '',
  is_exporation_date_valid: vigenciaOk ? 'True' : 'False',
  estado: vigenciaOk ? 'REGISTRADO' : 'RECHAZADO_VIGENCIA',
  fecha_registro: $now.toISO(),
  vigenciaOk: vigenciaOk,
  mensaje: vigenciaOk ? MSG_EXITO : MSG_VIGENCIA
} }];

const ctx = $json;
const fila = $('Get Session').first().json || {};
const estado = ctx.estadoActual || 'NUEVO';
const raw = String(ctx.texto || '').trim();

const MSG_NOMBRE = 'De acuerdo, haremos su registro sin pasaporte.\n\nPor favor escriba su *nombre completo* (nombres y apellidos), tal como aparecera en su pasaporte.';
const MSG_NOMBRE_ERROR = 'No pudimos leer su nombre. Por favor escriba su *nombre completo*: nombres y apellidos, por ejemplo: Juan Perez Lopez.';
const MSG_NACIMIENTO = 'Gracias. Ahora escriba su *fecha de nacimiento* en formato DD/MM/AAAA (por ejemplo: 05/03/1998).';
const MSG_NACIMIENTO_ERROR = 'Esa fecha no es valida. Por favor escriba su *fecha de nacimiento* en formato DD/MM/AAAA (por ejemplo: 05/03/1998).';
const MSG_CURP = 'Gracias. Ahora escriba su *CURP* o si no tiene, escribir N/A';
const MSG_CURP_ERROR = 'El formato no parece correcto. Por favor escriba su *CURP* de 18 caracteres, o escriba *N/A* si no cuenta con uno.';
const MSG_SEXO = 'Por ultimo, escriba su *sexo*: responda *M* para masculino o *F* para femenino.';
const MSG_SEXO_ERROR = 'No entendimos su respuesta. Responda *M* para masculino o *F* para femenino.';
const MSG_EXITO = 'Registro exitoso, sin embargo recuerda que necesitas tramitar tu pasaporte a tiempo para el viaje';

let nombre = fila.nombre || '';
let apellidos = fila.apellidos || '';
let fechaNacimiento = fila.fecha_nacimiento || '';
let curp = fila.curp_o_ine || '';
let sexo = fila.sexo || '';

let nuevoEstado = 'SP_ESPERANDO_NOMBRE';
let mensaje = MSG_NOMBRE;
let completo = false;

if (estado === 'SP_ESPERANDO_NOMBRE') {
  const partes = raw.split(/\s+/).filter(function (p) { return p.length > 0; });
  if (partes.length < 2) {
    nuevoEstado = 'SP_ESPERANDO_NOMBRE';
    mensaje = MSG_NOMBRE_ERROR;
  } else {
    const corte = partes.length >= 4 ? 2 : 1;
    nombre = partes.slice(0, corte).join(' ');
    apellidos = partes.slice(corte).join(' ');
    nuevoEstado = 'SP_ESPERANDO_NACIMIENTO';
    mensaje = MSG_NACIMIENTO;
  }
} else if (estado === 'SP_ESPERANDO_NACIMIENTO') {
  const m = raw.match(/^(\d{1,2})\s*[\/\-\.]\s*(\d{1,2})\s*[\/\-\.]\s*(\d{4})$/);
  let valida = false;
  if (m) {
    const d = parseInt(m[1], 10);
    const mo = parseInt(m[2], 10);
    const y = parseInt(m[3], 10);
    const f = new Date(Date.UTC(y, mo - 1, d));
    valida = y >= 1900 && y <= new Date().getUTCFullYear() && mo >= 1 && mo <= 12 && f.getUTCDate() === d && (f.getUTCMonth() + 1) === mo;
    if (valida) {
      fechaNacimiento = y + '-' + ('0' + mo).slice(-2) + '-' + ('0' + d).slice(-2);
    }
  }

  if (valida) {
    nuevoEstado = 'SP_ESPERANDO_CURP';
    mensaje = MSG_CURP;
  } else {
    nuevoEstado = 'SP_ESPERANDO_NACIMIENTO';
    mensaje = MSG_NACIMIENTO_ERROR;
  }
} else if (estado === 'SP_ESPERANDO_CURP') {
  const inputCurp = raw.toUpperCase().trim();

  if (inputCurp === 'N/A' || inputCurp === 'NA' || inputCurp === 'NO') {
    curp = 'N/A';
    nuevoEstado = 'SP_ESPERANDO_SEXO';
    mensaje = MSG_SEXO;
  } else {
    const curpTest = inputCurp.replace(/\s+/g, '');
    const regexCurp = /^[A-Z]{4}\d{6}[A-Z]{6}[A-Z0-9]\d$/;

    if (regexCurp.test(curpTest)) {
      curp = curpTest;
      nuevoEstado = 'SP_ESPERANDO_SEXO';
      mensaje = MSG_SEXO;
    } else {
      nuevoEstado = 'SP_ESPERANDO_CURP';
      mensaje = MSG_CURP_ERROR;
    }
  }
} else if (estado === 'SP_ESPERANDO_SEXO') {
  const s = raw.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z]/g, '');
  let leido = '';

  if (s === 'm' || s === 'h' || s === 'masculino' || s === 'hombre') {
    leido = 'M';
  } else if (s === 'f' || s === 'femenino' || s === 'mujer') {
    leido = 'F';
  }

  if (leido) {
    sexo = leido;
    nuevoEstado = 'REGISTRADO_SIN_PASAPORTE';
    mensaje = MSG_EXITO;
    completo = true;
  } else {
    nuevoEstado = 'SP_ESPERANDO_SEXO';
    mensaje = MSG_SEXO_ERROR;
  }
} else {
  nuevoEstado = 'SP_ESPERANDO_NOMBRE';
  mensaje = MSG_NOMBRE;
  nombre = '';
  apellidos = '';
  fechaNacimiento = '';
  curp = '';
  sexo = '';
}

return [{ 
  json: { 
    email: ctx.email || '',
    remote_jid: ctx.remoteJid, 
    numero: ctx.numero, 
    nombre: nombre, 
    apellidos: apellidos, 
    fecha_nacimiento: fechaNacimiento, 
    curp_o_ine: curp, 
    sexo: sexo, 
    estado: nuevoEstado, 
    mensaje: mensaje, 
    completo: completo, 
    fecha_registro: $now.toISO() 
  } 
}];

