const ctx = $json;
const fila = $('Get Session').first().json || {};
const estado = ctx.estadoActual || 'NUEVO';
const raw = String(ctx.texto || '').trim();

// Mensajes
const MSG_NOMBRE = 'De acuerdo, haremos su registro sin pasaporte.\n\nPor favor escriba su *nombre completo* (nombres y apellidos), tal como aparecera en su pasaporte.';
const MSG_NOMBRE_ERROR = 'No pudimos leer su nombre. Por favor escriba su *nombre completo*: nombres y apellidos, por ejemplo: Juan Perez Lopez.';
const MSG_NACIMIENTO = 'Gracias. Ahora escriba su *fecha de nacimiento* en formato DD/MM/AAAA (por ejemplo: 05/03/1998).';
const MSG_NACIMIENTO_ERROR = 'Esa fecha no es valida. Por favor escriba su *fecha de nacimiento* en formato DD/MM/AAAA (por ejemplo: 05/03/1998).';
const MSG_CURP = 'Gracias. Ahora escriba su *CURP* o si no tiene, escribir N/A';
const MSG_CURP_ERROR = 'El formato no parece correcto. Por favor escriba su *CURP* de 18 caracteres, o escriba *N/A* si no cuenta con uno.';
const MSG_SEXO = 'Por ultimo, escriba su *sexo*: responda *M* para masculino o *F* para femenino.';
const MSG_SEXO_ERROR = 'No entendimos su respuesta. Responda *M* para masculino o *F* para femenino.';
const MSG_EXITO = 'Registro exitoso, sin embargo recuerda que necesitas tramitar tu pasaporte a tiempo para el viaje';

// Variables
let nombre = fila.nombre || '';
let apellidos = fila.apellidos || '';
let fechaNacimiento = fila.fecha_nacimiento || '';
let curp = fila.curp_o_ine || '';
let sexo = fila.sexo || '';

let nuevoEstado = 'SP_ESPERANDO_NOMBRE';
let mensaje = MSG_NOMBRE;
let completo = false;

if (estado === 'SP_ESPERANDO_NOMBRE') {
  const partes = raw.split(/\s+/).filter(function (p) { return p.length > 0; });
  if (partes.length < 2) {
    nuevoEstado = 'SP_ESPERANDO_NOMBRE';
    mensaje = MSG_NOMBRE_ERROR;
  } else {
    const corte = partes.length >= 4 ? 2 : 1;
    nombre = partes.slice(0, corte).join(' ');
    apellidos = partes.slice(corte).join(' ');
    nuevoEstado = 'SP_ESPERANDO_NACIMIENTO';
    mensaje = MSG_NACIMIENTO;
  }
} else if (estado === 'SP_ESPERANDO_NACIMIENTO') {
  const m = raw.match(/^(\d{1,2})\s*[\/\-\.]\s*(\d{1,2})\s*[\/\-\.]\s*(\d{4})$/);
  let valida = false;
  if (m) {
    const d = parseInt(m[1], 10);
    const mo = parseInt(m[2], 10);
    const y = parseInt(m[3], 10);
    const f = new Date(Date.UTC(y, mo - 1, d));
    valida = y >= 1900 && y <= new Date().getUTCFullYear() && mo >= 1 && mo <= 12 && f.getUTCDate() === d && (f.getUTCMonth() + 1) === mo;
    if (valida) {
      fechaNacimiento = y + '-' + ('0' + mo).slice(-2) + '-' + ('0' + d).slice(-2);
    }
  }

  if (valida) {
    nuevoEstado = 'SP_ESPERANDO_CURP'; // Redirige al estado del CURP
    mensaje = MSG_CURP;
  } else {
    nuevoEstado = 'SP_ESPERANDO_NACIMIENTO';
    mensaje = MSG_NACIMIENTO_ERROR;
  }
} else if (estado === 'SP_ESPERANDO_CURP') {
  // Limpiar la entrada y volverla mayúsculas para facilitar validación
  const inputCurp = raw.toUpperCase().trim();

  if (inputCurp === 'N/A' || inputCurp === 'NA' || inputCurp === 'NO') {
    curp = 'N/A';
    nuevoEstado = 'SP_ESPERANDO_SEXO';
    mensaje = MSG_SEXO;
  } else {
    // Validar formato CURP eliminando espacios extra (4 letras, 6 números, 6 letras, 1 alfanumérico, 1 número)
    const curpTest = inputCurp.replace(/\s+/g, '');
    const regexCurp = /^[A-Z]{4}\d{6}[A-Z]{6}[A-Z0-9]\d$/;

    if (regexCurp.test(curpTest)) {
      curp = curpTest;
      nuevoEstado = 'SP_ESPERANDO_SEXO';
      mensaje = MSG_SEXO;
    } else {
      nuevoEstado = 'SP_ESPERANDO_CURP';
      mensaje = MSG_CURP_ERROR;
    }
  }
} else if (estado === 'SP_ESPERANDO_SEXO') {
  const s = raw.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z]/g, '');
  let leido = '';

  if (s === 'm' || s === 'h' || s === 'masculino' || s === 'hombre') {
    leido = 'M';
  } else if (s === 'f' || s === 'femenino' || s === 'mujer') {
    leido = 'F';
  }

  if (leido) {
    sexo = leido;
    nuevoEstado = 'REGISTRADO_SIN_PASAPORTE';
    mensaje = MSG_EXITO;
    completo = true;
  } else {
    nuevoEstado = 'SP_ESPERANDO_SEXO';
    mensaje = MSG_SEXO_ERROR;
  }
} else {
  nuevoEstado = 'SP_ESPERANDO_NOMBRE';
  mensaje = MSG_NOMBRE;
  nombre = '';
  apellidos = '';
  fechaNacimiento = '';
  curp = ''; // Resetear CURP
  sexo = '';
}

return [{ 
  json: { 
    remote_jid: ctx.remoteJid, 
    numero: ctx.numero, 
    email: ctx.email || '', 
    nombre: nombre, 
    apellidos: apellidos, 
    fecha_nacimiento: fechaNacimiento, 
    curp_o_ine: curp, 
    sexo: sexo, 
    estado: nuevoEstado, 
    mensaje: mensaje, 
    completo: completo, 
    fecha_registro: $now.toISO() 
  } 
}];
